        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-teal-400 via-vibrant-green to-teal-400"></div>
        <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X className="w-5 h-5" />
        </button>

        <div className="p-8 md:p-10">
           <div className="flex items-center gap-3 mb-6">
              <div className="w-12 h-12 bg-teal-100 dark:bg-teal-900/30 text-teal-600 dark:text-teal-400 rounded-full flex items-center justify-center">
                 <Sparkles className="w-6 h-6" />
              </div>
              <div>
                  <h2 className="text-2xl font-bold text-navy-900 dark:text-white">Welcome to SimpleAgentix!</h2>
                  <p className="text-sm text-slate-500 dark:text-slate-400 font-medium">Let's Automate Your Business</p>
              </div>
           </div>

           <div className="space-y-4 mb-8">
              <p className="text-lg font-semibold text-navy-900 dark:text-white">
                Hi {userName},
              </p>
