                                   className={`w-full text-left px-4 py-2.5 text-xs font-bold hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors ${language === l ? 'text-vibrant-orange' : 'text-slate-600 dark:text-slate-400'}`}
                               >
