                                    <div className="flex gap-1">
                                        {['HI', 'BN', 'EN'].map(l => (
                                            <span key={l} className="text-[9px] font-bold text-slate-500 bg-slate-800 px-1 py-0.5 rounded">{l}</span>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="hidden md:flex flex-col items-end">
                            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">Latency</div>
                            <div className="text-xl font-mono font-bold text-white">0.02s <span className="text-emerald-500 text-sm ml-1">Ultra-Fast</span></div>
                        </div>
                    </div>

                    {/* Visual Content Area */}
                    <div className="flex-1 relative z-10 py-6">

                        {/* CUSTOM MODE: Selection & Analysis */}
                        {activeTab === 'custom' && !customAnalysis && (
                            <div className="h-full flex flex-col justify-center animate-in fade-in slide-in-from-bottom-4 duration-500">
                                <div className="max-w-md mx-auto w-full space-y-6">
                                    <div className="space-y-4">
                                        <div className="space-y-2">
                                            <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Select Industry</label>
                                            <div className="grid grid-cols-2 gap-2">
                                                {Object.keys(INDUSTRIES).map(ind => (
                                                    <button 
                                                        key={ind}
                                                        onClick={() => { setSelectedIndustry(ind); setSelectedSegment(''); }}
                                                        className={`p-3 rounded-xl border text-left text-xs font-bold transition-all ${selectedIndustry === ind ? 'bg-white text-navy-900 border-white' : 'bg-slate-900/50 border-slate-700 text-slate-400 hover:border-slate-500'}`}
                                                    >
                                                        {ind}
                                                    </button>
                                                ))}
                                            </div>
                                        </div>

                                        {selectedIndustry && (
                                            <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
                                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Select Niche Segment</label>
                                                <div className="flex flex-wrap gap-2">
                                                    {INDUSTRIES[selectedIndustry].map(seg => (
                                                        <button 
                                                            key={seg}
                                                            onClick={() => setSelectedSegment(seg)}
                                                            className={`px-4 py-2 rounded-full border text-xs font-bold transition-all ${selectedSegment === seg ? 'bg-vibrant-orange text-white border-vibrant-orange' : 'bg-slate-900/50 border-slate-700 text-slate-400 hover:border-slate-500'}`}
                                                        >
                                                            {seg}
                                                        </button>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                    </div>

                                    <button 
                                        onClick={handleGenerateCustom}
                                        disabled={!selectedIndustry || !selectedSegment || isAnalyzing}
                                        className="w-full py-4 bg-gradient-to-r from-vibrant-orange to-red-500 text-white font-bold rounded-2xl shadow-xl shadow-orange-900/20 flex items-center justify-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:scale-[1.02]"
                                    >
                                        {isAnalyzing ? (
                                            <>
                                                <Loader2 className="w-5 h-5 animate-spin" /> Analyzing Business Logic...
                                            </>
                                        ) : (
                                            <>
                                                <Sparkles className="w-5 h-5" /> Generate Agent Workflow
                                            </>
                                        )}
                                    </button>
                                </div>
                            </div>
                        )}

                        {/* CUSTOM MODE: Result Display */}
                        {activeTab === 'custom' && customAnalysis && (
                            <div className="space-y-8 animate-in fade-in duration-500">
                                <div className="bg-[#0f172a]/50 p-6 rounded-2xl border border-vibrant-orange/30">
                                    <div className="flex items-start gap-4">
                                        <div className="p-2 bg-vibrant-orange/10 rounded-lg text-vibrant-orange mt-1">
                                            <BrainCircuit className="w-6 h-6" />
                                        </div>
                                        <div>
                                            <h5 className="text-white font-bold text-sm mb-2">AI Architect Recommendation</h5>
                                            <p className="text-slate-300 text-xs leading-relaxed whitespace-pre-line">
                                                {customAnalysis}
                                            </p>
                                        </div>
                                    </div>
                                    <button onClick={resetCustom} className="mt-4 text-xs font-bold text-slate-500 hover:text-white flex items-center gap-1">
                                        <RefreshCw className="w-3 h-3" /> Reset Builder
                                    </button>
                                </div>
                                {/* Fall through to generic step visualization below */}
                            </div>
                        )}

                        {/* STANDARD / GENERATED WORKFLOW VISUALIZATION */}
                        {((activeTab !== 'custom') || (activeTab === 'custom' && customAnalysis)) && (
                            <div className={`w-full flex flex-col md:flex-row justify-between items-start md:items-center relative gap-8 md:gap-0 transition-opacity duration-500 ${isAnimating ? 'opacity-20' : 'opacity-100'}`}>

                                {/* Connector Line Logic */}
                                <div className="hidden md:block absolute top-[2.5rem] left-[10%] right-[10%] h-[1px] bg-slate-800 z-0"></div>

                                {activeWorkflow.steps.map((step, idx) => (
                                    <div key={idx} className="relative z-10 flex flex-row md:flex-col items-center gap-6 flex-1 group">

                                        {/* Icon Orbit */}
                                        <div className="relative">
                                            <div className={`w-16 h-16 md:w-20 md:h-20 rounded-[2rem] border flex items-center justify-center transition-all duration-700 ${
                                                idx === 0 
                                                ? 'bg-emerald-500 border-emerald-400 text-navy-900 shadow-[0_0_40px_rgba(16,185,129,0.3)] scale-110 z-20' 
                                                : 'bg-[#1e293b] border-slate-700 text-slate-400 group-hover:border-slate-500'
                                            }`}>
                                                {step.isVoice ? <LiveVoiceWaveform /> : <step.icon className="w-8 h-8" />}
                                            </div>

                                            {/* Pulse Effect for current step */}
                                            {idx === 0 && (
                                                <div className="absolute inset-0 rounded-[2rem] bg-emerald-500/20 animate-ping -z-10"></div>
                                            )}
                                        </div>

                                        {/* Arrow for Desktop */}
                                        {idx < activeWorkflow.steps.length - 1 && (
                                            <div className="hidden md:block absolute top-[2.5rem] left-[65%] w-1/2 h-[1px] bg-gradient-to-r from-emerald-500/40 to-transparent"></div>
                                        )}

                                        {/* Text Content */}
                                        <div className="flex-1 text-left md:text-center md:px-2">
                                            <h5 className={`text-sm font-bold mb-1 transition-colors ${idx === 0 ? 'text-emerald-400' : 'text-white'}`}>
                                                {step.title}
                                            </h5>
                                            <p className="text-[11px] text-slate-500 leading-snug font-medium max-w-[140px] md:mx-auto">
                                                {step.desc}
                                            </p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Agentic Completion Signal */}
                    <div className="mt-12 p-6 rounded-3xl bg-slate-900/50 border border-slate-800 flex flex-col md:flex-row items-center justify-between gap-6 relative z-10 animate-in slide-in-from-bottom-4 duration-700 shadow-inner">
                        <div className="flex items-center gap-5">
                            <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.1)]">
                                <ShieldCheck className="w-8 h-8" />
                            </div>
                            <div>
                                <div className="text-white font-bold text-base mb-0.5">
                                    {activeTab === 'custom' && !customAnalysis ? 'Ready to Build' : 'Workflow Optimized & Deployed'}
                                </div>
                                <p className="text-slate-500 text-xs">
                                    {activeTab === 'custom' && !customAnalysis 
                                        ? 'Select your industry parameters to initialize the AI architect.' 
                                        : 'SimpleAgentix handled manual steps in 1.2 seconds. No manual intervention required.'}
                                </p>
                            </div>
                        </div>
                        {((activeTab !== 'custom') || (activeTab === 'custom' && customAnalysis)) && (
                            <button className="whitespace-nowrap px-8 py-3.5 bg-vibrant-orange hover:bg-orange-600 text-white font-bold rounded-2xl text-xs uppercase tracking-widest shadow-xl shadow-orange-900/20 transition-all flex items-center gap-2 group transform active:scale-95">
                                Launch This Agent <Play className="w-3 h-3 fill-current group-hover:translate-x-0.5 transition-transform"/>
                            </button>
                        )}
                    </div>

                </div>
            </div>

            {/* Language Promise */}
            <div className="mt-16 flex flex-wrap justify-center gap-10 opacity-60">
                <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                    <span className="text-sm font-bold text-slate-400">Hindi Voice Support</span>
                </div>
                <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                    <span className="text-sm font-bold text-slate-400">Bengali Voice Support</span>
                </div>
                <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                    <span className="text-sm font-bold text-slate-400">English Voice Support</span>
                </div>
            </div>
        </div>
    </section>
  );
};
